#!/usr/bin/env python3
"""Generate `_bc_rec_mul`'s shifted adds of `m1` and `m3` into the product.

Each site loads the handle from its slot, passes `n_len`, `n_value`, the
shift and `sub = 0`, and calls `_bc_shift_addsub`; `kshift_<P>` hands the
continuation the product's new digits (`shiftDs_add`) and the step's state
(`KMid.after`). The model site is `0x80005164`; the signed `m2` site is
`kara_m2` (`Dc/Mach/Bc/KaraShift.lean`).

Output (do not hand-edit): `Dc/Mach/Bc/KaraShiftSites.lean`.

    python3 scripts/dc/gen_kara_shift.py [--check]
"""
import pathlib
import sys

OUT = pathlib.Path(__file__).resolve().parents[2] / "Dc/Mach/Bc/KaraShiftSites.lean"

# Where `a0` (the product) comes from at the site.
A0 = {
    "a5": dict(a0hyp=" (hy15 : R 15 = BitVec.ofNat 64 y.rep.p)", a0doc=" (`a5` holds the product)",
               pre="", facts=", hy15", acc="", a0fact=""),
    "a0": dict(a0hyp=" (hy10 : R 10 = BitVec.ofNat 64 y.rep.p)", a0doc=" (`a0` holds the product)",
               pre="", facts=", hy10", acc="", a0fact="hy10"),
    "q": dict(a0hyp="", a0doc="",
              pre="  have hqs := cx.slot\n  have q2 := hqs.hi; have q3 := hqs.lo\n"
                  "  have hyp : y.rep.p = y.sb.pay := (hb.blocks y List.mem_cons_self).sPay\n",
              facts=", km.tr.q, km.hq", acc=" | exact hqs.acc", a0fact="hyp"),
}

# The shift (`a3`): the register facts it needs.
SHIFT = {
    "n": dict(sh="n", shdoc="n", shfacts=", km.tr.n"),
    "0": dict(sh="0", shdoc="0", shfacts=""),
    "2n": dict(sh="(2 * n)", shdoc="2*n", shfacts=", km.tr.n, kshl1"),
}

# (site, jal, handle, slot field, shift, product source)
SITES = [
    (0x80005164, 0x8000517c, "m3", "m3", "n", "a5"),
    (0x80005180, 0x80005198, "m3", "m3", "0", "q"),
    (0x80005468, 0x8000547c, "m1", "m1", "2n", "a0"),
    (0x80005480, 0x80005498, "m1", "m1", "n", "q"),
]

HEAD = """import Dc.Mach.Bc.KaraShift

/-!
# `_bc_rec_mul`'s shifted adds of `m1` and `m3` (generated)

Generated by `scripts/dc/gen_kara_shift.py`; do not hand-edit.
-/

namespace Dc.Mach

open Vsa.MemRepr Vsa.Sim VsaIris VsaIris.Inst VsaIris.Sym VsaIris.MallocFast
open LeanRV64DExecutable LeanRV64DExecutable.Functions Sail
open Dc.BcModel

set_option linter.unusedSimpArgs false

"""

TEMPLATE = '/-- `_bc_shift_addsub (*prod, {mname}, {shdoc}, 0)` at `0x{P}`{a0doc}. -/\ntheorem kshift_{P} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M0 M : Mem} {R0 R : Nat → BitVec 64} {sp q W n : Nat} {A B : List NumObj} {z : NumObj}\n    {y : NumObj} {H : Heap} {F : List Blk} (cx : RmCtx S R0 sp q W)\n    {hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2 : Hd}\n    (km : KMid S M0 M R0 R sp q W n z hu1 hu0 hv1 hv0 hd1 hd2 hm1 hm2 hm3 y)\n    (hb : BcHeap S M H F (y :: KList [] (kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2) A B z))\n    (hyo : y.Owns){a0hyp}\n    (hwp : 1 \u2264 (Hd.objIn (kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2) z {hm}).rep.len)\n    (hfit : {sh} + valCount (Hd.objIn (kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2) z {hm}).rep ≤\n      y.rep.len + y.rep.scale)\n    (hlt : dvalBE y.rep.ds + hdVal (Hd.objIn (kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2) z {hm}) *\n      10 ^ {sh} < 10 ^ (y.rep.len + y.rep.scale))\n    (hk : ∀ R2 M2 ds, KMid S M0 M2 R0 R2 sp q W n z hu1 hu0 hv1 hv0 hd1 hd2 hm1 hm2 hm3 (withDs y ds) →\n      BcHeap S M2 H F (withDs y ds :: KList [] (kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2) A B z) →\n      dvalBE ds = dvalBE y.rep.ds +\n        hdVal (Hd.objIn (kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2) z {hm}) * 10 ^ {sh} →\n      DW live S Q 0x{N}#64 R2 M2) :\n    DW live S Q 0x{P}#64 R M := by\n  generalize hhs : kHs hu1 hu0 hv1 hm1 hv0 hm2 hm3 hd1 hd2 = hs at hb hwp hfit hlt hk\n  generalize hw : Hd.objIn hs z {hm} = w at hwp hfit hlt hk\n  have hwL : w ∈ KList [] hs A B z := hw ▸ Hd.objIn_mem (hhs ▸ by simp) _ _ _ _\n  have hn := hb.nums w (List.mem_cons_of_mem _ hwL)\n  have hny := hb.nums y List.mem_cons_self\n  have pw : w.rep.p = Hd.p z {hm} := by rw [← hw, Hd.objIn_p]\n  have hS : HeapOwn S := fun a h1 h2 => hb.heap.own a h1 h2\n  have hsf := cx.frame\n  have hsl := hsf.lo; have hsh := hsf.hi; have hsa := hsf.al\n  have hW := cx.big\n  have ev : ldv .ld M (Hd.p z {hm} + 32) = BitVec.ofNat 64 w.rep.val := by rw [← pw]; exact hn.value\n  have el : ldv .lw M (Hd.p z {hm} + 4) = BitVec.ofNat 64 w.rep.len := by rw [← pw]; exact hn.len\n  num_facts hn\n  have h2 := km.st.rm.r2\n{pre}  bc_run hlive hS [h2, km.sl.{slot}, ev, el{facts}] at 0x{J}\n  all_goals first | exact frame_acc hsf (by omega) (by omega){acc} | skip\n  have yv1 := hny.shape.vLo; have yv2 := hny.shape.vHi\n  simp only [heapStart, heapEnd] at yv1 yv2\n  have ys := hny.shape; have ws := hn.shape\n  have hwl : w.rep.len ≤ w.rep.ds.length := by have := ws.dsLen; omega\n  have hc := noCarry_add ys.dsLen ys.dig hfit hwl hwp ws.dig hlt\n  apply st_{J} hlive\n  refine bc_shift_addsub_spec (w := w) (shift := {sh}) (sub := false) hlive hyo\n    (by bsimp []) ⟨hwL, hwp, hfit, hc⟩ hb (by bsimp [{a0fact}]) (by bsimp []) (by bsimp []) (by bsimp [])\n    (by bsimp []; rfl) ?_\n  intro R2 M2 hsh hb2\n  have hP : ∀ a, accBytes y.rep a → heapStart ≤ a ∧ a < heapEnd := fun a ha => by\n    simp only [accBytes, heapStart, heapEnd] at ha ⊢; omega\n  have kk : Keeps [1, 5, 6, 10, 11, 12, 13, 14, 15, 16, 17, 28] R2 R :=\n    (hsh.keeps.mono (by decide)).trans (by keeps_tac Keeps.refl _ _)\n  exact hk R2 M2 _ (km.after cx hsh.mem hP kk _) hb2\n    (shiftDs_add ys.dsLen ys.dig hfit hwl hwp ws.dig hc)\n\n'


def site(p, j, mname, slot, shift, a0):
    sub = dict(P="%08x" % p, J="%08x" % j, N="%08x" % (j + 4), mname=mname, hm="h" + mname,
               slot=slot, **SHIFT[shift], **A0[a0])
    sub["facts"] = SHIFT[shift]["shfacts"] + A0[a0]["facts"]
    s = TEMPLATE
    for k in ["a0hyp", "a0doc", "pre", "facts", "acc", "a0fact", "shdoc", "mname", "slot",
              "sh", "hm", "P", "J", "N"]:
        s = s.replace("{" + k + "}", sub[k])
    return s


def render():
    return HEAD + "".join(site(*x) for x in SITES) + "end Dc.Mach\n"


def main():
    text = render()
    if "--check" in sys.argv:
        if OUT.read_text() != text:
            sys.exit(f"{OUT} is stale; rerun {__file__}")
        return
    OUT.write_text(text)


if __name__ == "__main__":
    main()
